import "./spinner.css";

import type { ComponentProps } from "react";
import { cx } from "./cx";

export type SpinnerProps = ComponentProps<"span"> & {
  label?: string | undefined;
};

function Ticks() {
  return (
    <>
      <span />
      <span />
      <span />
    </>
  );
}

export function Spinner({ className, label, ...rest }: SpinnerProps) {
  if (label) {
    return (
      <span
        className={cx("ns-spinner", className)}
        role="status"
        aria-label={label}
        {...rest}
      >
        <Ticks />
      </span>
    );
  }

  return (
    <span
      className={cx("ns-spinner", className)}
      aria-hidden="true"
      {...rest}
    >
      <Ticks />
    </span>
  );
}

@layer components {
  .ns-spinner {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.14em;
    box-sizing: border-box;
    width: 1em;
    height: 1em;
    flex-shrink: 0;
    pointer-events: none;
    color: inherit;
  }

  .ns-spinner > span {
    display: block;
    width: 0.2em;
    height: 0.55em;
    border-radius: 1px;
    background: currentColor;
    opacity: 0.22;
    animation: ns-spinner-tick 0.9s var(--ease, cubic-bezier(0.22, 1, 0.36, 1))
      infinite;
  }

  .ns-spinner > span:nth-child(2) {
    animation-delay: 0.12s;
  }

  .ns-spinner > span:nth-child(3) {
    animation-delay: 0.24s;
  }

  @keyframes ns-spinner-tick {
    0%,
    70%,
    100% {
      opacity: 0.22;
      transform: none;
    }
    35% {
      opacity: 1;
      transform: translateY(0.08em);
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .ns-spinner > span {
      animation: none;
      opacity: 0.55;
      transform: none;
    }
  }
}
